from .betreuungsrechnung import _rechnungssumme
from .betraege import _geld_ergebnis
from .kalender import _auswahl, _text

_FAELLE = {'ratenlieferung_nettobetragsersatz': '§510III: Summe aller vom Verbraucher bis zum rechtlich frühestmöglichen Kündigungszeitpunkt zu entrichtenden Teilzahlungen. Stichtag und Zahlungsplan extern qualifizieren; keine Kürzung auf aktuell offene Raten, bereits gezahlte zum Umfang gehörende Raten bleiben enthalten. Keine Zahlungen erst nach dem maßgeblichen Vertragsende einbeziehen. Ergebnis ersetzt nur die Bezugsgröße Nettodarlehensbetrag für491II2Nr1, entscheidet nicht weitere Ausnahmen oder Widerrufsrechte.', 'ruecktritt_geldrueckgewaehr_einer_partei': '§346: ausschließlich rechtlich geschuldete Geldrückgewähr, Nutzungsherausgabe in Geld und Wertersatz einer bestimmten rückgewährpflichtigen Vertragspartei. Sachrückgabe nicht als zusätzliche Geldforderung bewerten; Wertersatz tritt an die Stelle der betreffenden Sachrückgabe. Kein doppeltes Erfassen von ursprünglichem Geldbetrag, Ersatzwert und denselben Nutzungen. Wertersatzausnahmen346III und Bewertungsmaßstab346II vorqualifiziert. Je Partei separat aufrufen; keine automatische Saldierung, Aufrechnung oder Durchbrechung von348.', 'bereicherung_geldkomponenten': '§818I/II: rechtlich zugeordnete Geldherausgabe, gezogene Nutzungen in Geld, erfasste Surrogate und an die Stelle nicht möglicher Herausgabe tretender Wertersatz. Originalgegenstand und an seine Stelle tretenden Wertersatz/Surrogat nicht doppelt einrechnen; physische Sachherausgabe bleibt gesondert. Dies ist die Summe VOR gesonderter Entreicherungsbegrenzung818III, verschärfter Haftung818IV/819/820 und Zahlungsanrechnung. Keine pauschale Addition beliebiger Ersatzansprüche oder Rechtsgrundprüfung.', 'auftrag_geldherausgabe': '§667: ausschließlich Geldbeträge, die rechtlich aus dem zur Auftragsausführung Erhaltenen oder aus der Geschäftsbesorgung Erlangten herauszugeben sind. Nur unterschiedliche, noch nicht in anderen Positionen enthaltene Beträge; Sachherausgabe nicht in Geld umdeuten und denselben Vermögenswert nicht als Eingang und Surrogat doppelt zählen. Aufwendungsersatz670 und Vorschüsse669 gesondert, keine automatische Saldierung oder Aufrechnung. Eigennutzungszinsen668 separat.', 'mietmangel_schaden_und_selbstbeseitigung': '§536aI/II: Summe rechtlich ersatzfähiger Geldschäden und erforderlicher Selbstbeseitigungsaufwendungen aus demselben abgegrenzten Mangelkomplex. Anspruchsvoraussetzungen und jeweilige Schadensbemessung249ff vorqualifizieren. Jeder wirtschaftliche Nachteil nur einmal, auch bei mehreren Anspruchsgrundlagen; als Selbstbeseitigung enthaltene Reparatur nicht nochmals als Schaden addieren. Mietminderung536 und bereits geleisteter Ersatz separat, keine automatische Kumulation desselben Ausfalls.'}

def schuldrecht_geldpositionssumme(regelfall=None, geldpositionen=None, einordnungsnachweis=None):
    """Qualifizierte überschneidungsfreie Geldpositionen desselben gesetzlichen Berechnungsumfangs exakt summieren."""
    _auswahl(regelfall,"regelfall",tuple(_FAELLE))
    summe = _rechnungssumme(geldpositionen,"geldpositionen")
    _text(einordnungsnachweis,"einordnungsnachweis")
    eingaben = dict(regelfall=regelfall, geldpositionen=geldpositionen, einordnungsnachweis=einordnungsnachweis)
    ergebnis = _geld_ergebnis(summe,'BGB_SCHULDRECHT_GELDPOSITIONSSUMME',eingaben,[dict(operation='Qualifizierte überschneidungsfreie Geldpositionen desselben gesetzlichen Berechnungsumfangs exakt summieren.')])
    ergebnis["hinweise"].extend(['Nur numerischer Summenbaustein für den ausdrücklich gewählten Normfall. Bei510 werden alle bis zum frühestmöglichen Kündigungszeitpunkt zu entrichtenden Raten erfasst, nicht nur offene. Bei346 je verpflichteter Partei getrennt; bei818 vor gesonderter Entreicherungs-/Haftungsprüfung. Keine automatische Aufrechnung, Sachbewertung oder Anspruchsentscheidung.',_FAELLE[regelfall]])
    return ergebnis
